local NE = DragonUI_NewEra
-- Addon/EncounterJournal/DataWotLK.lua — Wrath of the Lich King instance roster, tier=3.
--
-- HAND-SEEDED (not auto-generated — see the header this file replaced for why: no DB2 export
-- tool or WotLK loot database exists in this environment). Boss rosters + per-boss loot are
-- pulled from ReferenceAddons/atlasloot/AtlasLoot_WrathoftheLichKing/wrathofthelichking.lua
-- (an AtlasLoot data module the user added specifically for this). Extraction was scripted
-- (parsed AtlasLoot's `AtlasLoot_Data["Key"] = {...}` tables via luaparse, grouped by instance
-- using AtlasLoot's own section banners). AtlasLoot splits one boss's loot across many linked
-- pages for THREE independent reasons, which had to be told apart:
--   * pure pagination ("Archavon1"/"Archavon2", "..._A"/"..._H") — collapsed, same boss/same size/
--     same difficulty, just more items than fit one screen.
--   * raid size ("Koralon" vs "Koralon25Man") — KEPT SEPARATE: every raid loot row below carries
--     size=10 or size=25.
--   * raid Heroic mode, WotLK-3.3+ only (ICC / Ruby Sanctum / Trial of the Grand Crusader —
--     `raidHeroic=true` on those `add{}` instances) — KEPT SEPARATE: diff="h" on those rows,
--     absent = Normal. 5-man dungeon Normal/Heroic loot uses the same diff="n"/"h" tags, derived
--     from AtlasLoot's own #j1#(Normal)/#j3#(Heroic) row-group headers instead of a size split
--     (5-mans have no 10/25 axis).
-- None of this was hand-typed — treat item ids/pct/size/diff as faithful to that source,
-- cross-checkable by re-running the same extraction.
--
-- What ISN'T here yet (AtlasLoot is a loot browser — it doesn't carry this): boss ABILITIES/
-- sections (no rootSection/sections table — the Abilities tab shows the honest "No abilities
-- recorded" placeholder until hand-seeded, same as AbilitiesTBC.lua did for TBC raids), LORE
-- (no `desc` on instances or encounters), MAP DATA (no mapID/uiMapID/x/y — unused by this port
-- anyway, no dungeon maps on 3.3.5a), and remaining ART (no loreFDID/bgFDID, no creature
-- display/portrait ids — instance buttons are wired at the tail of this file; backdrop/lore/
-- boss-portrait BLPs are not yet shipped; an instance renders with the default tier background
-- until those FDIDs are sourced from retail's EJ DB2 and the BLPs are shipped into
-- Textures/EncounterJournal). All of these degrade gracefully in the renderer (EncounterPage.lua)
-- rather than erroring or faking data.
--
-- isRaid / minLevel are NOT from AtlasLoot either — they're well-established, stable WotLK
-- facts (dungeon/raid entry levels), the same category of "general knowledge" DataTBC.lua cited
-- "TBC LFGDungeons" for.
--
-- id numbering: this file's own placeholder range (90001+ for instances, instanceID*100+N for
-- encounters) — deliberately far outside retail JournalInstance/JournalEncounter id-space so it
-- can never collide with a real id if DB2-sourced fields get added to these same entries later.
--
-- Schema mirrors Data.lua/DataTBC.lua (same renderer, no code changes needed). Loaded by
-- DragonUI_NewEra.toc AFTER DataTBC.lua: APPENDS to NE.ej.DATA.instances, each tier=3.

NE.ej = NE.ej or {}
NE.ej.DATA = NE.ej.DATA or { instances = {} }
NE.ej.DATA.instances = NE.ej.DATA.instances or {}
local I = NE.ej.DATA.instances
local function add(t)
  t.tier = 3
  t.encounters = t.encounters or {}
  t.shell = (#t.encounters == 0)
  I[#I + 1] = t
end

